def sol2(arr: list[str]) -> int {
    n = len(arr);
    v = [-1 for _ in range(256)];
    m = 1;
    clen = 1;
    v[ord(arr[0])] = 0;
    for i in range(1, n) {
        lastIndex = v[ord(arr[i])];
        if (lastIndex == -1 or i - clen > lastIndex) {
            clen += 1;
        } else {
            m = max(m, clen);
            clen = i - lastIndex;
        }
        v[ord(arr[i])] = i;
    }
    m = max(m, clen);
    return m;
}

