""" Pull relevant data from a response object """
def cmc_get_data(
    jso: dict[str, object] | None, cmc_id: int, pair_symbol: str = 'USD'
) -> dict[str, float | None] | None {
    if not jso {
        return None;
    }
    data = jso.get('data', {}) as dict[str, object];
    specific_data = data.get(str(cmc_id), {}) as dict[str, object];
    quote = specific_data.get('quote', {}) as dict[str, object];
    symbol_data = quote.get(pair_symbol, {}) as dict[str, object];
    return {
        'price': symbol_data.get('price') as float | None,
        'volume': symbol_data.get('volume_24h') as float | None,
        'percent_change': symbol_data.get('percent_change_24h') as float | None,
        'market_cap': symbol_data.get('market_cap') as float | None,
    };
}
